$("#file").addEventListener("change", async (event) => {
  const file = event.target.files[0];
  if (!file) return;
  const current = ++task;
  resetReport();
  if (file.size > 25 * 1024 * 1024) {
    setStatus("This file exceeds the 25 MB inspection limit.", true);
    return;
  }
  setStatus("Reading " + file.name + " on this device\u2026");
  try {
    const bytes = await file.arrayBuffer();
    if (current === task) await run(bytes, file.name, false, current);
  } catch {
    if (current === task) setStatus("The file could not be read.", true);
  }
});
$("#demo").addEventListener("click", () => {
  $("#file").value = "";
  run(makeDemo(), "sample-proposal.docx", true).catch(() => setStatus("The sample could not be inspected.", true));
});
$("#categories").addEventListener("click", (event) => {
  const button = event.target.closest("button[data-category]");
  if (!button || !report) return;
  for (const chip of $("#categories").children) {
    chip.classList.toggle("selected", chip === button);
    chip.setAttribute("aria-pressed", String(chip === button));
  }
  render(button.dataset.category);
});
function download(bytes, filename, type) {
  const url = URL.createObjectURL(new Blob([bytes], { type }));
  const link = node("a");
  link.href = url;
  link.download = filename;
  document.body.append(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1e3);
}
$("#download-report").addEventListener("click", () => {
  if (report) download(JSON.stringify(report, null, 2), "word-sharing-report.json", "application/json");
});
$("#download-demo").addEventListener("click", () => download(makeDemo(), "sample-proposal.docx", "application/vnd.openxmlformats-officedocument.wordprocessingml.document"));
$("#clear").addEventListener("click", () => {
  task++;
  resetReport();
  $("#file").value = "";
  setStatus("Choose a document or try the sample.");
});
